import { DataTable, type DataTableColumn, type DataTableSelectionChangeDetail } from '@absoluteui/components/data-table';
import { instant, plainDate, type Instant, type PlainDate } from '@absoluteui/core';

interface Order {
  id: string;
  customer: string;
  total: number;
  placed: PlainDate;
  updated: Instant;
  paid: boolean;
}

const orders: Order[] = [
  { id: 'o-1001', customer: 'Acme Corp', total: 1250.5, placed: plainDate(2024, 3, 1), updated: instant(Date.UTC(2024, 2, 2, 9, 30)), paid: true },
  { id: 'o-1002', customer: 'Globex', total: 310, placed: plainDate(2024, 3, 4), updated: instant(Date.UTC(2024, 2, 4, 16, 0)), paid: false },
];
const columns: DataTableColumn<Order>[] = [
  { id: 'customer', header: 'Customer', accessor: (o) => o.customer },
  { id: 'total', header: 'Total', accessor: (o) => o.total, type: 'currency', currency: 'USD' },
  { id: 'placed', header: 'Placed', accessor: (o) => o.placed, type: 'date' },
  { id: 'updated', header: 'Updated', accessor: (o) => o.updated, type: 'datetime' },
  { id: 'paid', header: 'Paid', accessor: (o) => o.paid, type: 'boolean', sortable: false },
];
const host = document.createElement('div');
document.body.append(host);
const table = DataTable.create(host, {
  caption: 'Orders',
  columns,
  rows: orders,
  rowId: (o) => o.id,
  selection: 'multiple',
  pageSize: 25,
  pageSizes: [25, 50, 100],
  timezone: 'America/New_York',
  sort: { column: 'placed', direction: 'descending' },
});
host.addEventListener('aui-selection-change', (event) => {
  const { selected } = (event as CustomEvent<DataTableSelectionChangeDetail>).detail;
  host.dataset.selectedCount = String(selected.length);
});
table.setSelected(['o-1001']);

import { DataTable, type DataTablePageChangeDetail, type DataTableSort, type DataTableSortChangeDetail } from '@absoluteui/components/data-table';

interface User {
  id: string;
  name: string;
  email: string;
}

const host = document.createElement('div');
document.body.append(host);
const table = DataTable.create<User>(host, {
  caption: 'Users',
  mode: 'server',
  total: 0,
  rows: [],
  loading: true,
  rowId: (u) => u.id,
  columns: [
    { id: 'name', header: 'Name', accessor: (u) => u.name },
    { id: 'email', header: 'Email', accessor: (u) => u.email },
  ],
});
let sort: DataTableSort | null = null;
const load = async (page: number, pageSize: number): Promise<void> => {
  table.update({ loading: true });
  const query = new URLSearchParams({ page: String(page), size: String(pageSize), sort: sort ? `${sort.column}:${sort.direction}` : '' });
  const response = await fetch(`/api/users?${query.toString()}`);
  const body = (await response.json()) as { rows: User[]; total: number };
  table.update({ rows: body.rows, total: body.total, loading: false });
};
host.addEventListener('aui-sort-change', (event) => {
  sort = (event as CustomEvent<DataTableSortChangeDetail>).detail.sort;
  void load(table.page, table.pageSize ?? 25);
});
host.addEventListener('aui-page-change', (event) => {
  const { page, pageSize } = (event as CustomEvent<DataTablePageChangeDetail>).detail;
  void load(page, pageSize);
});
void load(1, 25);

