import {
  DataTable,
  DataTableColumnChooser,
  downloadCsv,
  type DataTableColumn,
  type DataTableState,
} from '@absoluteui/components/data-table';
import { instant, plainDate, type Instant, type PlainDate } from '@absoluteui/core';
import { Button } from '@absoluteui/components/button';

interface Ticket {
  id: string;
  title: string;
  status: 'open' | 'closed';
  priority: number;
  due: PlainDate;
  updated: Instant;
  description: string;
}

const tickets: Ticket[] = [
  { id: 'T-1', title: 'Login fails on Safari', status: 'open', priority: 1, due: plainDate(2026, 4, 1), updated: instant(Date.UTC(2026, 2, 20, 9, 0)), description: 'Steps: open /login in Safari 17.' },
  { id: 'T-2', title: 'Export button misaligned', status: 'closed', priority: 3, due: plainDate(2026, 3, 15), updated: instant(Date.UTC(2026, 2, 18, 16, 30)), description: 'Seen at 320 px.' },
];
const columns: DataTableColumn<Ticket>[] = [
  { id: 'id', header: 'Ticket', accessor: (t) => t.id, rowHeader: true, hideable: false },
  { id: 'title', header: 'Title', accessor: (t) => t.title, filter: 'text' },
  { id: 'status', header: 'Status', accessor: (t) => t.status, filter: 'enum', filterOptions: [{ value: 'open', label: 'Open' }, { value: 'closed', label: 'Closed' }] },
  { id: 'priority', header: 'Priority', accessor: (t) => t.priority, type: 'number', filter: 'number', minWidth: 80 },
  { id: 'due', header: 'Due', accessor: (t) => t.due, type: 'date', filter: 'date' },
  { id: 'updated', header: 'Updated', accessor: (t) => t.updated, type: 'datetime', filter: 'date' },
];

const toolbar = document.createElement('div');
const chooserButton = document.createElement('button');
chooserButton.type = 'button';
chooserButton.textContent = 'Columns';
Button.enhance(chooserButton);
const exportButton = document.createElement('button');
exportButton.type = 'button';
exportButton.textContent = 'Export CSV';
Button.enhance(exportButton);
toolbar.append(chooserButton, exportButton);
const host = document.createElement('div');
document.body.append(toolbar, host);

const STORAGE_KEY = 'tickets-table';
const table = DataTable.create(host, {
  caption: 'Tickets',
  columns,
  rows: tickets,
  rowId: (t) => t.id,
  selection: 'multiple',
  multiSort: true,
  searchable: true,
  resizable: true,
  pinnedColumns: { start: ['id'] },
  timezone: 'America/New_York',
  sort: [{ column: 'status', direction: 'descending' }, { column: 'priority', direction: 'ascending' }],
  renderDetail: (ticket, doc) => {
    const p = doc.createElement('p');
    p.textContent = ticket.description;
    return p;
  },
});
DataTableColumnChooser.create(chooserButton, table);

// Restore and save the view state (the table never persists anything itself).
const saved = localStorage.getItem(STORAGE_KEY);
if (saved !== null) {
  try {
    table.setState(JSON.parse(saved) as DataTableState);
  } catch {
    localStorage.removeItem(STORAGE_KEY);
  }
}
for (const type of ['aui-sort-change', 'aui-filter-change', 'aui-columns-change', 'aui-page-change']) {
  host.addEventListener(type, () => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(table.getState()));
  });
}

exportButton.addEventListener('click', () => {
  const rows = table.selected.length > 0 ? 'selected' : 'filtered';
  downloadCsv(table.toCsvBlob({ rows, bom: true }), 'tickets.csv');
});

import { DataTable, type DataTableColumn, type DataTableState } from '@absoluteui/components/data-table';

interface Customer {
  id: string;
  name: string;
  country: string;
  revenue: number;
}

const columns: DataTableColumn<Customer>[] = [
  { id: 'name', header: 'Name', accessor: (c) => c.name, filter: 'text' },
  { id: 'country', header: 'Country', accessor: (c) => c.country, filter: 'enum', filterOptions: [{ value: 'DE', label: 'Germany' }, { value: 'IN', label: 'India' }] },
  { id: 'revenue', header: 'Revenue', accessor: (c) => c.revenue, type: 'currency', currency: 'EUR', filter: 'number' },
];
const host = document.createElement('div');
document.body.append(host);
const table = DataTable.create<Customer>(host, {
  caption: 'Customers',
  mode: 'server',
  total: 0,
  rows: [],
  loading: true,
  rowId: (c) => c.id,
  columns,
  multiSort: true,
  searchable: true,
});

// One query shape for every user change: sort, filters, search, and page all come from getState().
let controller: AbortController | null = null;
const load = async (state: DataTableState): Promise<void> => {
  controller?.abort();
  controller = new AbortController();
  table.update({ loading: true });
  const response = await fetch('/api/customers/query', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sort: state.sort, filters: state.filters, search: state.search, page: state.page, pageSize: state.pageSize }),
    signal: controller.signal,
  });
  const body = (await response.json()) as { rows: Customer[]; total: number };
  table.update({ rows: body.rows, total: body.total, loading: false });
};
for (const type of ['aui-sort-change', 'aui-filter-change', 'aui-page-change']) {
  host.addEventListener(type, () => {
    load(table.getState()).catch((error: unknown) => {
      if (!(error instanceof DOMException && error.name === 'AbortError')) table.update({ loading: false });
    });
  });
}
void load(table.getState());

import { DataTable } from '@absoluteui/components/data-table';

interface Reading {
  id: string;
  sensor: string;
  value: number;
}

const readings: Reading[] = Array.from({ length: 100_000 }, (_, i) => ({ id: `r${String(i)}`, sensor: `Sensor ${String(i % 250)}`, value: (i * 37) % 1000 }));
const host = document.createElement('div');
document.body.append(host);
// Only the rows in view (plus an overscan) are in the DOM; the region is 70vh tall by default.
DataTable.create<Reading>(host, {
  caption: 'Sensor readings',
  rows: readings,
  rowId: (r) => r.id,
  pageSize: null,
  virtual: true,
  selection: 'multiple',
  columns: [
    { id: 'sensor', header: 'Sensor', accessor: (r) => r.sensor, filter: 'text' },
    { id: 'value', header: 'Value', accessor: (r) => r.value, type: 'number', filter: 'number' },
  ],
});
